import React, { useState, useEffect } from "react";
import styled from "styled-components";
import { motion } from "framer-motion";
import Card from "../components/Card";
import projectsData from "../projectlist.json";
import ImgBox from "../components/ImgBox";


const Container = styled.div`
  height: 100vh;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 0 10px;
  transition: all 0.3s ease-in-out;

  @media screen and (max-width:768px){
    flex-direction: column;
  }
`;

const Grid = styled(motion.div)`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 20px;
  width: ${({ $isExpanded }) => ($isExpanded ? "20%" : "100%")};
  transition: all 0.5s ease-in-out;
  align-items: center;
  justify-content: center;

  /* 📌 모바일에서는 아이콘 리스트가 한 줄로 정렬 */
  @media (max-width: 768px) {
    display: flex;
    width: 100%;
    gap: 0;
  }
`;

const SelectedProject = styled(motion.div)`
  display: flex;
  gap: 16px;
  position: relative;
  flex: ${({ $isVisible }) => ($isVisible ? 1 : 0)};
  background: ${({ theme }) => theme.background};
  color: ${({ theme }) => theme.text};
  padding: ${({ $isVisible }) => ($isVisible ? "20px" : "0")};
  border: 1px solid ${({ theme }) => theme.text};
  border-radius: 10px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
  transition: all 0.5s ease-in-out;
  max-width: ${({ $isVisible }) => ($isVisible ? "100%" : "0")};
  opacity: ${({ $isVisible }) => ($isVisible ? 1 : 0)};

  @media screen and (max-width:1240px){
    flex-direction: column;

  }
  @media screen and (max-width:768px){
    width: 90%;

  }
`;
const MainTitle = styled.h1`
  display: none;
  @media screen and (max-width:768px) {
    display: block;
  }
`
const LeftBox = styled.div`
  width: 80%;
  text-align: left;
  @media screen and (max-width:768px){
    width: 100%;
  }
`
const RightBox = styled.div`

`
const Title = styled.p`
  font-size: 45px;
  font-weight: bold;
  margin-bottom: 10px;
`
const TextBox = styled.div`
  text-align: left;
`
const Span = styled.span`
  @media screen and (max-width:768px){
    font-size: 14px;
  }
`
const Strong = styled.strong`
  font-size: 20px;

  @media screen and (max-width:768px){
    font-size: 16px;
  }
`
const CloseButton = styled(motion.button)`
  position: absolute;
  right: 10px;
  top: -10px;
  margin-top: 20px;
  padding: 10px 15px;
  border: none;
  background: ${({ theme }) => theme.text};
  color: ${({ theme }) => theme.background};
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  border-radius: 5px;
  transition: 0.3s;

  &:hover {
    background: ${({ theme }) => theme.background};
    color: ${({ theme }) => theme.text};
    border: 1px solid ${({ theme }) => theme.text};
  }

  @media screen and (max-width:768px){
    padding: 5px 10px;
  }
`;
const DemoBox = styled.div`
  display: flex;
  gap: 10px;
  margin-top: 30px;
`
const DemoBtn = styled.button`
  color: ${({ theme }) => theme.text};
  border-radius: 6px;
  border: 1px solid ${({ theme }) => theme.text};;
  background-color: ${({ theme }) => theme.background};
  width: 300px;
`
const DemoLink = styled.a`
  color: ${({ theme }) => theme.text};
  text-decoration: none;
  width: 100%;
  height: 100%;
  display: block;
  padding: 10px;
  font-weight: bold;
  cursor: pointer;

  &:hover{
    color: ${({ theme }) => theme.background};
    background-color: ${({ theme }) => theme.text};
  }
`

const parseBoldText = (text) => {
  return text.split(/(\*\*.*?\*\*)/g).map((part, index) => {
    if (part.startsWith("**") && part.endsWith("**")) {
      return <Strong key={index} >{part.slice(2, -2)}</Strong>;
    }
    return part;
  });
};
const Projects = () => {
  const [selectedProject, setSelectedProject] = useState(null);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  const { projects } = projectsData; // JSON 파일에서 projects 가져오기

  // 화면 크기 감지하여 반응형 적용
  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return (
    <Container>
      {/* 왼쪽 카드 목록 */}
      <MainTitle>Projects</MainTitle>
      <Grid
        $isExpanded={!!selectedProject && !isMobile}
        animate={{
          width: selectedProject && !isMobile ? "20%" : "100%",
        }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
      >
        {projects.map((project) => (
          <motion.div
            key={project.id}
            initial={{ opacity: 1, scale: 1 }}
            animate={{
              display: selectedProject?.id === project.id ? "none" : "block",
              scale: selectedProject?.id === project.id ? 0 : 1,
            }}
            transition={{ duration: 0.3 }}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={() => setSelectedProject(project)}
          >
           <Card 
        title={project.title} 
        text={project.text} 
        icon={project.icon} 
        isMobile={isMobile} 
      />
          </motion.div>
        ))}
      </Grid>

      {/* 오른쪽 상세보기 박스 */}
      <SelectedProject
        initial={{ opacity: 0, x: 50, scale: 0.9 }}
        animate={{
          opacity: selectedProject ? 1 : 0,
          x: selectedProject ? 0 : 50,
          scale: selectedProject ? 1 : 0.9,
        }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
        $isVisible={!!selectedProject}
      >
        {selectedProject && (
          <>
          <LeftBox>
          <Title>{selectedProject.title}</Title>
            <p><strong>타입:</strong> {selectedProject.compatible}</p>
            <p><strong>사용 기술:</strong> {selectedProject.skill}</p>
            <p><strong>기간:</strong> {selectedProject.period}</p>

            <ImgBox images={selectedProject.img} />
            <DemoBox>
              <DemoBtn> 
                <DemoLink href={selectedProject.demourl} target="_blank" rel="noopener noreferrer">Demo</DemoLink>
              </DemoBtn>
              <DemoBtn> <DemoLink href={selectedProject.sourceurl} target="_blank" rel="noopener noreferrer">Source</DemoLink>
              </DemoBtn>
             
            </DemoBox>
          </LeftBox>
            <RightBox>
            <TextBox>
              <p><strong>설명:</strong></p>
              <motion.p>
                {selectedProject.explanation.split("\n\n").map((paragraph, index) => (
                  <Span key={index}>
                    {parseBoldText(paragraph)}
                    <br /><br />
                  </Span>
                ))}
              </motion.p>
            </TextBox>
            </RightBox>
           
           

            {/* 닫기 버튼 */}
            <CloseButton
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={() => setSelectedProject(null)}
            >
              X
            </CloseButton>
          </>
        )}
      </SelectedProject>
    </Container>
  );
};

export default Projects;
