import React from "react";
import { Link as ScrollLink } from "react-scroll";  // ✅ react-scroll 사용
import { Link as RouterLink, useLocation } from "react-router-dom"; // ✅ react-router-dom 사용
import styled from "styled-components";
import { useTheme } from "../../context/ThemeContext";
const Logo = styled.h1`
  cursor: pointer;
  @media screen and (max-width:768px){
    display: none;
  }

`
const Nav = styled.nav`
  position: fixed;
  top: 0;
  width: 100%;
  background: ${({ theme }) => theme.navBackground};
  color: ${({ theme }) => theme.navText};
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 30px;
  z-index: 100;
  @media screen and (max-width:768px){
    flex-flow: column;
    gap: 10px;
  }
`;

const NavLinks = styled.div`
  a {
    color: ${({ theme }) => theme.navText};
    text-decoration: none;
    margin: 0 10px;
    cursor: pointer;
  }
`;

const ThemeButton = styled.button`
  width: 60px;
  height: 60px;
  position: fixed;
  top: 85px;
  right: 20px;
  background: none;
  border: none;
  color: ${({ theme }) => theme.navText};
  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
  transform: rotate(180deg);
  @media screen and (max-width:768px){
    align-self: flex-end;
  }
`;
const Img = styled.img`
  width: 50px;
  height: 50px;
  object-fit: cover;
`
const Line = styled.span`
  content: "";
  position: absolute;
  top: 50px;
  left: 48%;
  display: inline-block;
  width: 2px;
  height: 60px;
  background-color: ${({ theme }) => theme.navText};
  @media screen and (max-width:768px){
    height: 100px;
  }
`
const Link = styled(ScrollLink)`
  &:hover {
    font-weight: bold;
  }
`
const Header = () => {
  const { theme, toggleTheme } = useTheme(); // ✅ 테마 변경 기능 추가
  const location = useLocation(); // ✅ 현재 경로 확인
  const themeLabel =
    theme === "light" ? "assets/light.png" : "assets/dark.png";
  return (
    <Nav>
      {location.pathname === "/" ? (
        <RouterLink to="/portfolio"><h1>YoonHo</h1></RouterLink> // ✅ 홈으로 이동
      ) : (
        <ScrollLink to="home" smooth={true} duration={500}>
          <Logo>YoonHo</Logo>
        </ScrollLink>
      )}

      <NavLinks>
        {location.pathname === "/portfolio/home" && ( // ✅ 홈에서만 스크롤 링크 사용
          <>
            <Link to="home" smooth={true} duration={500}>Home</Link>
            <Link to="about" smooth={true} duration={500}>About</Link>
            <Link to="projects" smooth={true} duration={500}>Projects</Link>
            <Link to="contact" smooth={true} duration={500}>Contact</Link>
          </>
        )}
      </NavLinks>

      <ThemeButton onClick={toggleTheme}> 
        <Line></Line>
        <Img src={themeLabel}></Img>
      </ThemeButton>
    </Nav>
  );
};

export default Header;
