import React from "react";
import styled from "styled-components";

const Container = styled.div`
  position: relative;
  display: flex;
  flex-flow: column;
  gap: 5px;
  margin-top: 20px;
  @media screen and (max-width:740px){
    align-items: center;
  }
`;
const Title = styled.p`
    font-weight: bold;
`
const ImgsBox = styled.div`
    display: flex;
    gap: 5px;
    @media screen and (max-width:500px){
    flex-direction: column;
    align-items: center;
  }
`
const Img = styled.img`
  width: 200px;
  height: 150px;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
  transition: transform 0.3s ease-in-out;
  
  &:hover {
    transform: scale(1.1);
  }
  &:nth-child(2){
    @media screen and (max-width:500px){
    display: none;
  }
  }
  &:nth-child(3){
    @media screen and (max-width:740px){
    display: none;
  }
  }
  @media screen and (max-width:740px){
      width: 50%;
  }
  @media screen and (max-width:500px){
      width: 100%;
  }
`;

const ImgBox = ({ images }) => {
  if (!images || images.length !== 3) return null; // 이미지가 3개가 아닐 경우 렌더링 안함

  return (
    <Container>
    <Title>스크린샷</Title>
    <ImgsBox>
      <Img src={images[0]} alt="Project Image 1" />
      <Img src={images[1]} alt="Project Image 2" />
      <Img src={images[2]} alt="Project Image 3" />
    </ImgsBox>
    </Container>
  );
};

export default ImgBox;
