import React, { useState, useEffect } from "react";
import styled, { keyframes } from "styled-components";
import { motion } from "framer-motion";
import About from "./About";
import Projects from "./Projects";
import Contact from "./Contact";

/** ✅ 전체 컨테이너 스타일 */
const Container = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
  color: ${({ theme }) => theme.text};
  text-align: center;
  position: relative; 
  overflow: hidden;
`;

/** ✅ LP판 스타일 타이틀 박스 */
const LPRecord = styled(motion.div)`
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  border: 1px solid #cec5f1;
  background: repeating-radial-gradient(
    circle, 
    #111 0%, 
    #000 2%, 
    #111 4%,
    #000 6%
  ); 
  border-radius: 50%;
  box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.5);
  width: 600px;
  height: 600px;
  position: relative;
  overflow: hidden;

  @media screen and (max-width:768px){
    width: 350px;
    height: 350px;
  }

  &:before {
    content: "";
    position: absolute;
    width: 250px;
    height: 250px;
    background: #cec5f1;
    border-radius: 50%;
    z-index: 5;
    @media screen and (max-width:768px) {
      width: 150px;
      height: 150px;
    }
  }
`;

/** ✅ 애니메이션이 적용된 타이틀 */
const Title = styled(motion.h1)`
  color: #fff;
  font-size: 50px;
 
  text-align: center;
  z-index: 100;
  @media screen and (max-width:768px){
    font-size: 30px;
  }
`;
const Tonearm = styled(motion.div)`
  position: absolute;
  top: 120px;
  width: 150px;
  height: 10px;
  background: #8d7ddf;
  border-radius: 5px;
  transform-origin: left center;
  transform: rotate(-10deg);

  &:after {
    content: "";
    position: absolute;
    right: 0;
    width: 10px;
    height: 20px;
    background: #8d7ddf;
    border-radius: 5px;
  }

  @media screen and (max-width:768px){
    top: 250px;
    width: 110px;
  }
`;
/** ✅ 스크롤 진행 바 스타일 */
const ScrollTrack = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 5px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 10px;
  overflow: hidden;
  z-index: 100;
`;

const ProgressBar = styled.div`
  position: fixed;
  top: 0px;
  height: 5px;
  background: ${({ theme }) => theme.scrollbackground};
  width: ${({ $progress }) => $progress}%;
  transition: width 0.2s ease-out;
`;
const floatAnimation = keyframes`
  0% { transform: translateY(0px) rotate(0deg); opacity: 0.8; }
  50% { transform: translateY(-20px) rotate(10deg); opacity: 1; }
  100% { transform: translateY(0px) rotate(0deg); opacity: 0.8; }
`;

/** ✅ 떠다니는 음표 스타일 */
const Note = styled(motion.span)`
  position: absolute;
  font-size: ${({ size }) => `${size}rem`};
  color: ${({ theme }) => theme.text};
  opacity: 0.7;
  animation: ${floatAnimation} ${({ duration }) => duration}s ease-in-out infinite;
`;


/** ✅ 회전 애니메이션 */
const spinAnimation = {
  rotate: [0, 360],
  transition: { duration: 10, ease: "linear", repeat: Infinity }
};
const tonearmAnimation = {
  playing: { rotate: 20, transition: { duration: 1, ease: "easeOut" } },
  stopped: { rotate: -10, transition: { duration: 1, ease: "easeOut" } }
};
const Home = () => {
  const [scrollProgress, setScrollProgress] = useState(0);
  const [isSpinning, setIsSpinning] = useState(true); // LP 회전 여부

  useEffect(() => {
    const handleScroll = () => {
      const scrollTop = window.scrollY;
      const docHeight = document.documentElement.scrollHeight - window.innerHeight;
      const progress = (scrollTop / docHeight) * 100;
      setScrollProgress(progress);
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);
  
  const fixedNotes = [
    { icon: "♬", size: 1.5, left: "10%", top: "10%", duration: 4 },
    { icon: "♪", size: 1.8, left: "40%", top: "5%", duration: 3.5 },
    { icon: "♫", size: 2,   left: "80%", top: "10%", duration: 4.2 },
    { icon: "♩", size: 1.3, left: "5%",  top: "40%", duration: 3.8 },
    { icon: "♬", size: 1.6, left: "85%", top: "40%", duration: 4.5 },
    { icon: "♪", size: 1.4, left: "10%", top: "80%", duration: 3.7 },
    { icon: "♫", size: 1.7, left: "40%", top: "90%", duration: 4.1 },
    { icon: "♩", size: 1.2, left: "80%", top: "80%", duration: 3.9 },
    { icon: "♬", size: 1.5, left: "25%", top: "30%", duration: 4 },
    { icon: "♪", size: 1.8, left: "65%", top: "30%", duration: 4.3 },
    { icon: "♪", size: 1.4, left: "25%", top: "60%", duration: 3.7 },
    { icon: "♫", size: 1.7, left: "65%", top: "60%", duration: 4.1 },
    { icon: "♩", size: 1.2, left: "50%", top: "20%", duration: 3.9 },
    { icon: "♬", size: 1.5, left: "50%", top: "80%", duration: 4 },
    { icon: "♪", size: 1.8, left: "50%", top: "50%", duration: 4.3 },
  ];
  


  return (
    <>
      {/* ✅ 스크롤 진행 바 */}
      <ScrollTrack>
        <ProgressBar $progress={scrollProgress} />
      </ScrollTrack>
    
      <Container id="home">
      {fixedNotes.map(({ icon, size, left, top, duration }, index) => (
          <Note key={index} size={size} style={{ left, top }} duration={duration}>
            {icon}
          </Note>
        ))}
        {/* ✅ LP판 스타일 적용 */}

        <LPRecord
          animate={isSpinning ? spinAnimation : {}}
          onClick={() => setIsSpinning(!isSpinning)}
        >
          <Title>YoonHo</Title>
          <Title>Portfolio</Title>
        </LPRecord>
        <Tonearm
          animate={isSpinning ? "playing" : "stopped"}
          variants={tonearmAnimation}
        />
       
      </Container>

      {/* ✅ 섹션 스크롤 페이드 인 애니메이션 적용 */}
      <motion.div
        id="about"
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, amount: 0.3 }}
        transition={{ duration: 0.6 }}
      >
        
        <About />
      </motion.div>

      <motion.div
        id="projects"
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, amount: 0.3 }}
        transition={{ duration: 0.6 }}
      >
        <Projects />
      </motion.div>

      <motion.div
        id="contact"
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, amount: 0.3 }}
        transition={{ duration: 0.6 }}
      >
        <Contact />
      </motion.div>
    </>
  );
};

export default Home;
