import React from "react";
import styled from "styled-components";

const Wrapper = styled.div`
  width: 100%;
  height: 100vh;
  display: flex;

  @media screen and (max-width: 768px) {
    margin-top: 50px;
  }
`;

const Container = styled.div`
  position: relative;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
`;

const Title = styled.h2`
  font-size: 50px;
  margin-bottom: 20px;
`;

const ContactLeft = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
`;

const ContactInfo = styled.div`
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 10px;
  color: ${({ theme }) => theme.contactColor};
  
  @media screen and (max-width: 768px) {
    font-size: 20px;
    margin-bottom: 5px;
  }
`;

const Alink = styled.a`
  font-size: 16px;
  cursor: pointer;
  color: ${({ theme }) => theme.contactColor};
  text-decoration: none;
  &:hover {
    color: #cec5f1;
  }
`;

const CopyText = styled.span`
  font-size: 16px;
  cursor: pointer;
  color: ${({ theme }) => theme.contactColor};
  
  &:hover {
    color: #cec5f1;
  }
`;

const contactDetails = [
  { label: "E-mail", value: "jjzs115@gmail.com", link: "mailto:jjzs115@gmail.com" },
  { label: "GitHub", value: "https://github.com/yoonholeeeee", link: "https://github.com/yoonholeeeee" },
];

const Contact = () => {
  const phoneNumber = "010.5660.9843";

  const copyToClipboard = async (text) => {
    try {
      await navigator.clipboard.writeText(text);
      alert("📋 전화번호가 복사되었습니다!");
    } catch (err) {
      console.error("클립보드 복사 실패:", err);
    }
  };

  return (
    <Wrapper>
      <Container>
        <Title>Thank you 🎵</Title>
        <ContactLeft>
          <ContactInfo>제 포트폴리오를 끝까지 봐주셔서 감사합니다.</ContactInfo>
          <ContactInfo style={{ marginBottom: "20px" }}>항상 발전하는 개발자가 되겠습니다.</ContactInfo>

          {/* 전화번호 복사 기능 */}
          <ContactInfo>
            Tel <CopyText onClick={() => copyToClipboard(phoneNumber)}>{phoneNumber}</CopyText>
          </ContactInfo>

          {/* 나머지 연락처 정보 */}
          {contactDetails.map(({ label, value, link }) => (
            <ContactInfo key={label}>
              {label}{" "}
              {link ? <Alink href={link} target="_blank">{value}</Alink> : <span>{value}</span>}
            </ContactInfo>
          ))}
        </ContactLeft>
      </Container>
    </Wrapper>
  );
};

export default Contact;
