import React from "react";
import styled from "styled-components";

const CardContainer = styled.div`
  background: ${({ theme }) => theme.background};
  padding: 20px;
  border: 1px solid ${({ theme }) => theme.text};
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  cursor: pointer;
  
  /* 모바일에서 아이콘만 표시할 경우 */
  ${({ $isMobile }) => $isMobile && `
    width: 60px;
    height: 60px;
    padding: 5px;
    background: none;
    box-shadow: none;
    
  `}
`;

const Title = styled.h3`
  cursor: pointer;
  margin-bottom: 10px;
  font-size: 18px;
  color: ${({ theme }) => theme.text};
  ${({ $isMobile }) => $isMobile && `
    display: none;
  `}
`;

const Skill = styled.p`
  cursor: pointer;
  color: ${({ theme }) => theme.text};
  font-size: 14px;
  
  ${({ $isMobile }) => $isMobile && `
    display: none;
  `}
`;

const Icon = styled.img`
  width: 50px;
  height: 50px;
  object-fit: contain;

  /* ✅ isMobile이 true일 때만 표시 */
  ${({ $isMobile }) => ($isMobile ? "display: block;" : "display: none;")}
`;


const Card = ({ title, text, icon, isMobile }) => {
  return (
    <CardContainer $isMobile={isMobile}>
      {isMobile ? (
        <Icon src={icon} alt={title} $isMobile={isMobile} />
      ) : (
        <>
          <Title>{title}</Title>
          <Skill>{text}</Skill>
        </>
      )}
    </CardContainer>
  );
};

export default Card;
