import React, { useState } from "react";
import { useNavigate } from "react-router-dom"; // ✅ 페이지 이동
import styled from "styled-components";
import { motion } from "framer-motion";

const Container = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
  background: ${({ theme }) => theme.background};
  color: ${({ theme }) => theme.text};
  text-align: center;
  overflow: hidden;
`;

const Letter = styled(motion.span)`
  display: inline-block;
  font-size: 4rem; /* ✅ 글자 크기 확대 */
  font-weight: bold;
  margin: 0 5px;
`;

const StartButton = styled.button`
  background: ${({ theme }) => theme.text};
  color: ${({ theme }) => theme.background};
  padding: 12px 25px;
  border-radius: 5px;
  font-size: 1.5rem;
  font-weight: bold;
  margin-top: 30px;
  border: none;
  cursor: pointer;
  transition: 0.3s;

  &:hover {
    background: ${({ theme }) => theme.background};
    color: ${({ theme }) => theme.text};
    border: 1px solid ${({ theme }) => theme.text};
  }
`;

/** ✅ 더 넓게 퍼지는 애니메이션 */
const explodeAnimation = (index) => ({
  hidden: { opacity: 1, y: 0, scale: 1, rotate: 0 },
  visible: {
    opacity: 0,
    y: [0, Math.random() * -500 + 50], // ✅ 더 높이 튀도록 조정 (-500px까지 이동)
    x: [0, Math.random() * 600 - 300], // ✅ 좌우로 최대 600px 퍼지도록 조정
    scale: [1, 2, 0], // ✅ 두 배 커졌다가 사라짐
    rotate: [0, Math.random() * 720 - 360], // ✅ 더 큰 회전 효과 (-360° ~ 360°)
    transition: { duration: 1.5, ease: "easeInOut" }, // ✅ 더 부드러운 폭발 효과
  },
});

const Intro = () => {
  const navigate = useNavigate();
  const [isExploding, setIsExploding] = useState(false);
  const text = "Welcome!"; // ✅ 텍스트를 조각내어 처리

  const handleStart = () => {
    setIsExploding(true);
  };

  return (
    <Container>
      {!isExploding ? (
        <>
          <motion.h1 initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 1 }}>
            포트폴리오를 시작하시겠습니까?
          </motion.h1>
          <StartButton onClick={handleStart}>시작하기</StartButton>
        </>
      ) : (
        <motion.div
          initial="hidden"
          animate="visible"
          onAnimationComplete={() => navigate("/portfolio/home")} // ✅ 애니메이션 완료 후 페이지 이동
        >
          {text.split("").map((letter, index) => (
            <Letter key={index} variants={explodeAnimation(index)}>
              {letter}
            </Letter>
          ))}
        </motion.div>
      )}
    </Container>
  );
};

export default Intro;
