import React from "react";
import styled from "styled-components";
import Skill from "./Skill";
import { AiOutlineUser, AiOutlinePhone, AiOutlineMail } from "react-icons/ai";
import { BiCake, BiMap, BiBook } from "react-icons/bi";

const Container = styled.div`
  height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  @media screen and (max-width:768px) {
    height: 150vh;
    margin-bottom: 80px;
  }
`;

const Title = styled.h2`
  font-size: 2.5rem;
  margin-bottom: 20px;
`;
const SubTitleBox = styled.div`
  @media screen and (max-width:768px) {
    max-width: 400px;
  }
`
const Paragraph = styled.p`
  font-size: 1.2rem;
  color: ${({ theme }) => theme.text};
  margin-bottom: 15px;
  text-align: center;
`;

const ContentsBox = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  margin-top: 20px;
`;

const LeftBox = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  
`;

const InfoGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(2, 1fr); /* 2열 배치 */
  gap: 30px; /* 간격 조절 */
  width: 100%;
  max-width: 600px; /* 최대 너비 설정 */
  @media screen and (max-width:768px){
    gap: 10px;
  }
  
`;

const InfoItem = styled.div`
  display: flex;
  align-items: center;
  justify-content: flex-start;
  background: ${({ theme }) => theme.background};
  color: ${({ theme }) => theme.text};
  border: 1px solid ${({ theme }) => theme.text};
  padding: 12px 15px;
  border-radius: 10px;
  font-size: 1.2rem;
  font-weight: bold;
  text-align: left;
  gap: 10px; /* 아이콘과 텍스트 간격 */
`;

const IconWrapper = styled.span`
  font-size: 1.5rem;
  margin-top: 2px;
`;
const TextBox = styled.div`
  padding: 5px;
  @media screen and (max-width:768px){
    font-size: 15px;
    margin: 0;
  }
`
const Label = styled.p`
  text-align: left;
  margin: 0;
  @media screen and (max-width:768px){
    margin: 0;
  }
`;

const Value = styled.p`
  margin: 0;
 @media screen and (max-width:768px){
    margin: 0;
  }
`;

const RightBox = styled.div`
  margin-left: 50px;

  @media screen and (max-width:768px) {
    margin-left: 0;
    margin-top: 30px;
  }
`;

const About = () => {
  const personalInfo = [
    { label: "이름", value: "이윤호", icon: <AiOutlineUser /> },
    { label: "연락처", value: "010-5660-9843", icon: <AiOutlinePhone /> },
    { label: "생년월일", value: "95.02.26", icon: <BiCake /> },
    { label: "이메일", value: "jjzs115@naver.com", icon: <AiOutlineMail /> },
    { label: "위치", value: "경기도 고양시", icon: <BiMap /> },
    { label: "학력", value: "안산대학(인터넷정보과)", icon: <BiBook /> },
  ];

  return (
    <Container>
      <Title>About me</Title>
      <SubTitleBox>
      <Paragraph>
        안녕하세요! 사용자 경험을 최우선으로 생각하는 주니어 웹 개발자입니다.
      </Paragraph>
      <Paragraph>
        최신 기술을 탐구하고, 접근성을 고려한 UI를 구현하며, 성능 최적화를 통해 최고의 웹 사이트을 만드는 것이 목표입니다.
      </Paragraph>

      </SubTitleBox>
      <ContentsBox>
        <LeftBox>
          <InfoGrid>
            {personalInfo.map((item, index) => (
              <InfoItem key={index}>
                <IconWrapper>{item.icon}</IconWrapper>
                <TextBox>
                <Label>{item.label}</Label>
                <Value>{item.value}</Value>
                </TextBox>
              </InfoItem>
            ))}
          </InfoGrid>
        </LeftBox>

        <RightBox>
          <Skill />
        </RightBox>
      </ContentsBox>
    </Container>
  );
};

export default About;
